// Decrypt the credentials the Driplare app stores encrypted at rest.
//
// The app keeps tokens in "chatbot"."Integration".config as
// v1:<iv>:<authTag>:<ciphertext> (AES-256-GCM), so this step reverses that
// before any token is used to call Meta.
//
// Values that do NOT start with "v1:" are legacy plaintext and pass through
// untouched. That is deliberate: it makes this node a no-op until the backfill
// script runs, so it can be deployed and tested while every row is still
// plaintext.
//
// Requires NODE_FUNCTION_ALLOW_BUILTIN to include "crypto".

const crypto = require('crypto');

const SECRET_FIELDS = [
  'accessToken', 'pageToken', 'pageAccessToken', 'instagramAccessToken',
  'userAccessTokenLongLived', 'appSecret', 'clientSecret', 'verifyToken',
  'webhookVerifyToken', 'refreshToken', 'botToken', 'apiKey',
];

const rawKey =
  (typeof $env !== 'undefined' && $env.INTEGRATION_ENCRYPTION_KEY) ||
  (typeof process !== 'undefined' && process.env && process.env.INTEGRATION_ENCRYPTION_KEY);

if (!rawKey) {
  throw new Error('INTEGRATION_ENCRYPTION_KEY is not set in the n8n environment.');
}

const key = Buffer.from(String(rawKey).trim(), 'base64');

if (key.length !== 32) {
  throw new Error('INTEGRATION_ENCRYPTION_KEY must decode to exactly 32 bytes; got ' + key.length + '.');
}

function decrypt(value) {
  if (typeof value !== 'string' || value.indexOf('v1:') !== 0) return value;

  const parts = value.split(':');
  if (parts.length !== 4) throw new Error('Malformed encrypted value: expected 4 parts.');

  const iv = Buffer.from(parts[1], 'base64');
  const authTag = Buffer.from(parts[2], 'base64');
  const ciphertext = Buffer.from(parts[3], 'base64');

  const decipher = crypto.createDecipheriv('aes-256-gcm', key, iv, { authTagLength: 16 });
  decipher.setAuthTag(authTag);

  return Buffer.concat([decipher.update(ciphertext), decipher.final()]).toString('utf8');
}

return items.map((item) => {
  const json = { ...item.json };

  for (const field of SECRET_FIELDS) {
    if (field in json) json[field] = decrypt(json[field]);
  }

  return { json };
});
